SELECT tt.term_taxonomy_id, tt.term_id, t.name, t.slug, tt.taxonomy, tt.count FROM wp_buDIJ_term_taxonomy tt JOIN wp_buDIJ_terms t ON t.term_id=tt.term_id WHERE tt.taxonomy='pa_presentacion';
SELECT tr.term_taxonomy_id, t.slug FROM wp_buDIJ_term_relationships tr JOIN wp_buDIJ_term_taxonomy tt ON tt.term_taxonomy_id=tr.term_taxonomy_id JOIN wp_buDIJ_terms t ON t.term_id=tt.term_id WHERE tt.taxonomy='product_visibility' AND tr.object_id=15229;